python3 << 'PYEOF'
import base64, json, urllib.request, ssl

GITHUB_TOKEN = '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'
REPO = 'ibb142/ivx-holdings-platform'
BRANCH = 'main'
ctx = ssl.create_default_context()

files = [
    {
        'path': 'backend/services/ivx-voice-brain.ts',
        'message': 'feat: IVX Smart Voice Brain v1.0.0 — ChatGPT-level conversation memory, context-aware responses, topic detection, follow-up handling'
    },
    {
        'path': 'backend/api/ivx-signalwire-api.ts',
        'message': 'feat: Wire smart voice brain into SignalWire API — answerSmartVoiceQuestion replaces stateless answerVoiceQuestion, adds /voice/brain status endpoint'
    },
    {
        'path': 'backend/hono.ts',
        'message': 'feat: Add /api/ivx/signalwire/voice/brain route for smart voice brain status + active conversation monitoring'
    },
]

for f in files:
    file_path = f['path']
    with open(file_path, 'rb') as fh:
        content = base64.b64encode(fh.read()).decode('ascii')

    # Get current SHA
    req = urllib.request.Request(
        f'https://api.github.com/repos/{REPO}/contents/{file_path}?ref={BRANCH}',
        headers={'Authorization': f'token {GITHUB_TOKEN}', 'Accept': 'application/vnd.github+json'}
    )
    sha = None
    try:
        with urllib.request.urlopen(req, context=ctx) as resp:
            body = json.loads(resp.read().decode('utf-8'))
            sha = body.get('sha')
    except Exception:
        pass

    payload = json.dumps({
        'message': f['message'],
        'content': content,
        'branch': BRANCH,
        **({'sha': sha} if sha else {})
    }).encode('utf-8')

    req = urllib.request.Request(
        f'https://api.github.com/repos/{REPO}/contents/{file_path}',
        data=payload,
        method='PUT',
        headers={
            'Authorization': f'token {GITHUB_TOKEN}',
            'Content-Type': 'application/json',
            'Accept': 'application/vnd.github+json',
        }
    )

    try:
        with urllib.request.urlopen(req, context=ctx) as resp:
            body = json.loads(resp.read().decode('utf-8'))
            if 'commit' in body:
                print(f"✅ {file_path} → SHA {body['commit']['sha'][:12]}")
    except urllib.error.HTTPError as e:
        body = json.loads(e.read().decode('utf-8'))
        print(f"❌ {file_path} HTTP {e.code}: {body.get('message','')[:200]}")
